import React from "react";
import NavBar from "../../Components/NavBar/NavBar";
import MainHeading from "../../Components/Headings/MainHeading";

function About() {
  return (
    <div className=" text-white">
      <NavBar page={"About"} />
      <div className=" flex flex-col  justify-center">
        
          <MainHeading text={"About Solar Explore"} />
          <p>
            Welcome to Solar Explore, your trusted partner in discovering,
            learning about, and adopting solar energy solutions. We are
            dedicated to creating a sustainable future by helping individuals,
            businesses, and communities unlock the vast potential of solar
            power.
          </p>
      </div>
    </div>
  );
}

export default About;
